-- Study Abroad country content, BATCH 12: Slovenia, Iceland, Luxembourg, Ukraine, Uzbekistan.
-- Researched from public sources in November 2026 (see backend/TODO_country_tables.md for what still needs checking).
-- Text blocks fill the columns on countries; subject / course rows are linked to subjects / specializations
-- (country_sections.subject_id / specialization_id) so the website links them to those pages.
-- Replaces the earlier '[Sample]' / '[Placeholder]' rows of these 5 countries. Safe to re-run.
-- Requires alembic revision e6a3c9d1f4b7 (alembic upgrade head).
BEGIN;
DELETE FROM country_sections WHERE country_id IN (SELECT id FROM countries WHERE slug IN ('slovenia', 'iceland', 'luxembourg', 'ukraine', 'uzbekistan'));
UPDATE countries SET why_title = 'Why study in Slovenia?', why_body = '<p>Slovenia is a safe, green EU country with the University of Ljubljana at its centre. It offers EU-recognised degrees, a growing set of English-taught programmes and easy travel to Italy, Austria and Croatia.</p><ul><li>EU-recognised degrees</li><li>English-taught Master''s programmes at several universities</li><li>Study time counts (at half rate) towards permanent residence</li><li>Safe, compact and outdoors-friendly country</li></ul>', visa_title = 'Residence permit requirements', visa_body = '<p>Non-EU students need a <strong>temporary residence permit for studies</strong>. Applicants who cannot enter without a visa follow a different procedure, so check with the Slovenian embassy.</p><ul><li>Proof of enrolment at a Slovenian institution</li><li>Private health insurance (compulsory for non-EU students)</li><li>Proof of funds and accommodation</li><li>The permit is usually valid until the end of student status (30 September) and must be renewed before it expires</li><li>Study time counts as half of the period for permanent residence</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Slovenian administrative unit and the University of Ljubljana site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>Non-EU applicants use the university''s call for enrolment. The 2026/27 call was published on 30 January 2026 with selection on 25-26 August 2026; the next call is for 2027/28.</p><ul><li>Academic transcripts and certificates, apostilled</li><li>Language proof (English or Slovene)</li><li>Motivation letter and CV for Master''s programmes</li><li>Entrance test or portfolio for some programmes</li><li>Passport copy and photographs</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>Non-EU citizens from countries without a bilateral agreement generally pay tuition. Amounts come from each university''s price list and depend on the programme.</p><ul><li>Tuition: roughly €2,000-€8,000 a year for many programmes (estimate; see the University of Ljubljana price list)</li><li>Living costs: about €600-€1,000 a month (estimate)</li><li>Private health insurance is required</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate with required subjects</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>Language:</strong> IELTS 6.0 or equivalent for English-taught programmes; Slovene for local programmes</li></ul>' WHERE slug = 'slovenia';
UPDATE countries SET why_title = 'Why study in Iceland?', why_body = '<p>Iceland offers small, research-focused universities with strengths in geology, renewable energy, environment, fisheries and creative fields, set in a safe country with unique nature.</p><ul><li>Leading renewable energy and geosciences research</li><li>English-taught Master''s programmes at the University of Iceland</li><li>Small classes and close contact with staff</li><li>Very safe, high quality of life</li></ul>', visa_title = 'Student residence permit', visa_body = '<p>Non-EEA students apply for a <strong>student residence permit</strong> from the Directorate of Immigration <em>before</em> arriving in Iceland, once they have an acceptance letter.</p><ul><li>Acceptance letter from an Icelandic university</li><li>Private health insurance for the first three months with minimum cover of ISK 2,000,000</li><li>Permit processing fee: ISK 70,000 (island.is)</li><li>Proof of funds and accommodation</li><li>Reported from 8 July 2026: student permit holders may work up to 60% of full time without a separate work permit</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official island.is and the University of Iceland site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>You apply directly to the university; the University of Iceland lists 1 February as the deadline for Bachelor''s and Master''s programmes (sources also mention earlier permit deadlines).</p><ul><li>Academic transcripts and certificates</li><li>English proficiency proof</li><li>Motivation letter, CV and references for Master''s programmes</li><li>Passport copy and photographs</li><li>Processing fee for non-EEA applicants (reported at ISK 20,000)</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>Iceland has ended free tuition for most non-EEA students. The University of Iceland says a tuition fee applies to non-EEA citizens for 2026-27, while students enrolled in autumn 2025 or earlier stay on the old structure.</p><ul><li>Tuition: fee levels were not fully set when sources were checked and may vary by programme, so check the university</li><li>Registration fee: reported at ISK 100,000 for 2026-27</li><li>Living costs: roughly €1,100-€1,600 a month (estimate; Iceland is expensive)</li><li>Permit and insurance costs apply</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate with required subjects</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>Language:</strong> IELTS 6.0-6.5 or equivalent for English-taught programmes</li></ul>' WHERE slug = 'iceland';
UPDATE countries SET why_title = 'Why study in Luxembourg?', why_body = '<p>Luxembourg is a multilingual EU country and global finance hub. The University of Luxembourg has low fees and strong programmes in finance, law, computer science and European studies.</p><ul><li>Multilingual (English, French, German) University of Luxembourg</li><li>Low university fees</li><li>Leading finance, fintech and EU institutions</li><li>Central location in Western Europe</li></ul>', visa_title = 'Visa and residence permit', visa_body = '<p>Non-EU students staying over 90 days need a <strong>student residence permit</strong>. Deloitte reports that from 1 October 2026 first-time applicants must obtain a <strong>Visa D</strong> before coming.</p><ul><li>Admission letter and proof of enrolment</li><li>Proof of funds and accommodation</li><li>Health cover for the whole semester (the university can collect contributions with fees)</li><li>Renew the permit at least 30 days before it expires</li><li>Work: reported limits of about 15 hours a week in term and 40 hours in holidays, with first-year Bachelor''s restrictions; check guichet.lu</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official guichet.lu and the University of Luxembourg site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>Applications for 2026/27 are closed for non-EU applicants without a Luxembourg permit; 2027/28 applications open in 2027.</p><ul><li>Academic transcripts and certificates, apostilled</li><li>Language proof (English, French or German depending on programme)</li><li>Motivation letter and CV for Master''s programmes</li><li>Application fee: reported at €100</li><li>Passport copy and photographs</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>University of Luxembourg fees are low, but sources differ.</p><ul><li>Tuition: reported at about €400 a semester for most programmes (some sources report €200 from the third semester and €200 per semester for many Master''s)</li><li>Application fee: €100 (reported)</li><li>Living costs: about €1,000-€1,500 a month (estimate; Luxembourg is expensive)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate with required subjects</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>Language:</strong> English, French or German at B2/C1 depending on the programme</li></ul>' WHERE slug = 'luxembourg';
UPDATE countries SET why_title = 'Why study in Ukraine?', why_body = '<p>Ukraine has long attracted international students to medicine, dentistry, engineering and IT at low fees. The war has changed the situation, so check security guidance and university status before committing.</p><ul><li>Low tuition for medicine, dentistry and engineering</li><li>English-taught programmes at many universities</li><li>Established medical education tradition</li><li>Government portal Study in Ukraine lists participating universities</li></ul>', visa_title = 'Visa requirements', visa_body = '<p>Students who need a visa apply for a <strong>Type D student visa</strong> at a Ukrainian embassy or consulate. Check your government''s travel advice, as the conflict affects entry.</p><ul><li>Invitation to study (some universities now request it through a unified electronic system from 2026)</li><li>Valid passport, signed application form and photographs</li><li>Health insurance and proof of the consular fee</li><li>Medical certificate confirming health status</li><li>Travel advice: international students are advised to stay in touch with their consular services</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Ukrainian embassy and the Study in Ukraine portal site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>You apply directly to each university or through the Study in Ukraine portal.</p><ul><li>Secondary school or university diploma and transcripts</li><li>Passport copy with colour photo</li><li>Medical certificate</li><li>Entrance interview or test for medicine</li><li>English proficiency proof</li><li>Invitation letter request</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>The government portal lists medical programmes (medicine, dentistry, pharmacy, nursing) at about €1,500-€5,000 a year. Costs vary by university, city and language of instruction.</p><ul><li>Medicine and related: about €1,500-€5,000 a year (portal figure)</li><li>Engineering and IT: from about US$1,300 a year for some bachelor''s programmes (one university example)</li><li>Living costs: about €250-€500 a month (estimate)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate; medicine needs biology and chemistry</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>Language:</strong> English proof for English-taught programmes; Ukrainian or Russian for local programmes</li></ul>' WHERE slug = 'ukraine';
UPDATE countries SET why_title = 'Why study in Uzbekistan?', why_body = '<p>Uzbekistan is rapidly opening up higher education with new international branch campuses, such as Westminster International University in Tashkent, and low living costs.</p><ul><li>English-taught degrees at WIUT and other international branches</li><li>Low living costs</li><li>Growing economy and student opportunities</li><li>Rich history and culture (Samarkand, Bukhara)</li></ul>', visa_title = 'Visa requirements', visa_body = '<p>Visa rules depend on your nationality. Students normally need a <strong>student visa</strong> based on an invitation from the university. This search returned no official visa guidance, so confirm everything with the embassy.</p><ul><li>Admission letter and invitation from the university</li><li>Passport and application form</li><li>Proof of funds or tuition payment</li><li>Registration with migration authorities after arrival</li><li>Check the e-visa and student category with the Uzbek embassy</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Uzbek embassy and your university site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>You apply directly to each university. WIUT lists its own application steps on each course page; one third-party listing gives an admission period of 1 June to 30 September 2026.</p><ul><li>Academic transcripts and certificates</li><li>English proficiency proof</li><li>Motivation letter for postgraduate programmes</li><li>Entrance tests for some programmes</li><li>Passport copy and photographs</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>Costs differ for domestic and international students.</p><ul><li>WIUT MSc Public Health: about 75,870,000 UZS for international students (domestic: 54,439,200 UZS)</li><li>Other programmes: check each university; undergraduate fees were not found</li><li>Living costs: about US$250-$500 a month (estimate)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate with good results</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>Language:</strong> IELTS 5.5-6.5 or equivalent for English-taught programmes</li></ul>' WHERE slug = 'uzbekistan';
COMMIT;
